import fs from '\''node:fs/promises'\'';
process.env.CREW_DATA_DIR='\''data/w2-browser-proof'\'';
const { startServer, createContext, child } = await import(new URL('\''./scripts/acceptance-runtime.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const { writeFile }=fs;
const server=await startServer();
try {
  const ctx=createContext(server.url,{},[]);
  await ctx.signup('\''owner'\'',{name:'\''Browser'\'',email:'\''browser@work.test'\'',password:'\''browser-password-2026'\''});
  const org=(await ctx.api('\''POST'\'','\''/orgs'\'',{name:'\''Browser proof'\''})).organization;
  const project=(await ctx.api('\''POST'\'','\''/orgs/'\''+org.id+'\''/projects'\'',{key:'\''BROW'\'',name:'\''Browser board'\''})).project;
  const issue=(await ctx.api('\''POST'\'','\''/projects/'\''+project.id+'\''/issues'\'',{title:'\''Drag with a real pointer'\''})).issue;
  await writeFile('\''/tmp/w2-browser.py'\'',Buffer.from('\'''\'','\''base64'\''));
  const report=await child('\''/usr/bin/python3'\'',['\''/tmp/w2-browser.py'\''],{env:{...process.env,CREW_BROWSER_URL:server.url,WORK_IDS:JSON.stringify({projectId:project.id,issueId:issue.id,targetId:project.statuses[1].id})},deadline:45000});
  console.log(report.stdout);
} finally { await server.stop(); }
NODE
'

